-- Project status changes and all fixture records roll back; no provider is invoked.
begin;
create temp table availability_results(check_name text,passed boolean);
do $test$
declare staff uuid;member_id uuid;candidate uuid;ops uuid:=gen_random_uuid();ref text:='MTL-QA-'||upper(left(replace(gen_random_uuid()::text,'-',''),12));token text:='AvailabilityFixture'||replace(gen_random_uuid()::text,'-','');pid uuid;source_doc jsonb;roles jsonb;r jsonb;blocked boolean;payload jsonb;tid uuid;existing_ref text;existing_version bigint;team_before jsonb;members_before jsonb;
begin
 select user_id into staff from private_website_lab.member_roles where role='full_admin' limit 1;
 for candidate in select id from auth.users where email_confirmed_at is not null and private_website_lab.assigned_role(id)='member' and private_website_lab.account_allowed(id) order by id loop
  perform set_config('request.jwt.claim.sub',candidate::text,true);
  if public.website_my_profile_completion()>=80 then member_id:=candidate;exit;end if;
 end loop;
 assert member_id is not null,'A verified eligible staging member is required';
 select published into source_doc from private_website_content.documents where key='project:MTL-DA-001';
 roles:=source_doc->'roles';
 assert staff is not null and source_doc is not null,'Staging administrator and base document required';
 insert into public.website_project_briefs(project_ref,title,roles) values(ref,token,roles);
 insert into private_website_content.documents(key,kind,label,draft,published,published_at) values('project:'||ref,'project',token,source_doc,source_doc,now());
 insert into private_website_lab.market_proposals(owner_id,title,description,state,project_ref,reviewed_at) values(staff,token,token||' Public project description for isolated testing.','approved',ref,now()) returning id into pid;
 insert into private_website_lab.project_publications(nonce,proposal_id,published_by,published_at) values(gen_random_uuid(),pid,staff,now());
 perform set_config('request.jwt.claim.sub',staff::text,true);
 payload:=jsonb_build_object('key','project:'||ref,'state','closed','expected_publication_version',1,'confirmed',true,'note','Synthetic availability test reason');
 blocked:=false;begin perform public.website_content_admin('project_status',payload||'{"confirmed":false}'::jsonb);exception when raise_exception then blocked:=true;end;assert blocked,'Change accepted without confirmation';
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 blocked:=false;begin perform public.website_content_admin('project_status',payload);exception when insufficient_privilege then blocked:=true;end;assert blocked,'Member changed project status';
 execute 'set local role authenticated';
 assert public.website_my_profile_completion()>=80,'Controlled test member must be eligible to prove intake enforcement';
 insert into public.website_project_interests(user_id,project_ref,participation,primary_role,motivation,contribution,answers,terms_version) values(member_id,ref,'team',roles->>0,repeat('fixture ',5),repeat('fixture ',8),'{"commitment_response":"yes"}','2026-09-03-v1');
 execute 'reset role';
 delete from public.website_project_interests where user_id=member_id and project_ref=ref;
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values(ops,'availability-'||ops||'@example.invalid',now(),'{"full_name":"Availability operations fixture"}');
 insert into private_website_lab.member_roles(user_id,role) values(ops,'operations_admin');
 perform set_config('request.jwt.claim.sub',ops::text,true);
 r:=public.website_content_admin('project_status',payload);assert r->>'state'='closed' and r->>'publication_version'='2','Operations administrator cannot close intake';
 assert (public.website_project_publications(ref)->>'total')::int=1,'Closed brief disappeared from public catalogue';
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 r:=public.website_lab_community('feed',jsonb_build_object('q',token));assert exists(select 1 from jsonb_array_elements(r->'rows')x where x->>'project_ref'=ref),'Closed brief disappeared from Connect discovery';
 execute 'set local role authenticated';
 blocked:=false;begin insert into public.website_project_interests(user_id,project_ref,participation,primary_role,motivation,contribution,answers,terms_version) values(member_id,ref,'team',roles->>0,repeat('fixture ',5),repeat('fixture ',8),'{"commitment_response":"yes"}','2026-09-03-v1');exception when insufficient_privilege then blocked:=true;end;
 execute 'reset role';assert blocked,'Closed intake accepted direct authenticated application';
 insert into availability_results values('Confirmed operations change closes direct applications while keeping the brief and Connect discovery visible; members cannot change status',true);
 perform set_config('request.jwt.claim.sub',staff::text,true);
 blocked:=false;begin perform public.website_content_admin('project_status',payload);exception when serialization_failure then blocked:=true;end;assert blocked,'Stale availability write accepted';
 r:=public.website_content_admin('project_status',payload||'{"expected_publication_version":2}'::jsonb);assert r->>'unchanged'='true','Same state was not idempotent';
 r:=public.website_content_admin('project_status',payload||'{"state":"archived","expected_publication_version":2}'::jsonb);assert r->>'publication_version'='3','Archive version not advanced';
 assert (public.website_project_publications(ref)->>'total')::int=0,'Archived brief remains in public discovery';
 assert public.website_content_public('project:'||ref)->0->>'archived'='true','Static renderer lacks archive metadata';
 perform set_config('request.jwt.claim.sub',member_id::text,true);
 r:=public.website_lab_community('feed',jsonb_build_object('q',token));assert not exists(select 1 from jsonb_array_elements(r->'rows')x where x->>'project_ref'=ref),'Archived approved proposal remains in unified discovery';
 r:=public.website_market_proposals('approved',jsonb_build_object('q',token));assert not exists(select 1 from jsonb_array_elements(r->'rows')x where x->>'project_ref'=ref),'Archived proposal remains in approved-project list';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 r:=public.website_content_admin('project_status',payload||'{"state":"open","expected_publication_version":3}'::jsonb);assert r->>'publication_version'='4','Restore did not advance version';
 assert (public.website_project_publications(ref)->>'total')::int=1,'Restored brief missing from discovery';
 assert (select count(*)=3 from private_website_content.project_status_history where project_ref=ref),'Reasoned status history missing or duplicated';
 insert into availability_results values('Archive hides public/Connect discovery; stale writes are rejected, repeated state does not duplicate audit and reopening restores visibility',true);
 select id,project_ref,to_jsonb(t) into tid,existing_ref,team_before from public.website_project_teams t where coordinator_id=staff and status='active' order by id limit 1;
 assert tid is not null,'An existing administrator-owned staging Lab is required';
 select jsonb_agg(to_jsonb(m) order by user_id) into members_before from public.website_project_team_members m where team_id=tid;
 select publication_version into existing_version from public.website_project_briefs where project_ref=existing_ref;
 perform public.website_content_admin('project_status',jsonb_build_object('key','project:'||existing_ref,'state','archived','expected_publication_version',existing_version,'confirmed',true,'note','Synthetic existing-Lab preservation test'));
 perform public.website_lab('workspace',jsonb_build_object('team_id',tid));
 assert (select to_jsonb(t)=team_before from public.website_project_teams t where id=tid),'Archiving changed existing Lab state';
 assert (select jsonb_agg(to_jsonb(m) order by user_id)=members_before from public.website_project_team_members m where team_id=tid),'Archiving changed membership or access';
 assert not has_table_privilege('authenticated','private_website_content.project_status_history','SELECT') and not has_function_privilege('authenticated','private_website_content.project_status(jsonb)','EXECUTE'),'Private status history/helper exposed directly';
 insert into availability_results values('Existing active Lab and membership/access stay unchanged; private audit and helper remain inaccessible',true);
end $test$;
select * from availability_results;
rollback;
